import 'package:dio/dio.dart';import '../config/app_config.dart';import '../services/token_store.dart';
class ApiClient {ApiClient(this.tokens){dio=Dio(BaseOptions(baseUrl:AppConfig.apiBaseUrl,connectTimeout:const Duration(seconds:12),receiveTimeout:const Duration(seconds:15),headers:{'Accept':'application/json'}));dio.interceptors.add(InterceptorsWrapper(onRequest:(o,h)async{final t=await tokens.access();if(t!=null)o.headers['Authorization']='Bearer $t';h.next(o);},onError:(e,h)async{if(e.response?.statusCode!=401||e.requestOptions.extra['retried']==true)return h.next(e);try{final r=await tokens.refresh();if(r==null)return h.next(e);final response=await Dio(BaseOptions(baseUrl:AppConfig.apiBaseUrl)).post('/auth/refresh',data:{'refreshToken':r});await tokens.save(response.data['data']['session']);final o=e.requestOptions;o.extra['retried']=true;o.headers['Authorization']='Bearer ${await tokens.access()}';h.resolve(await dio.fetch(o));}catch(_){await tokens.clear();h.next(e);}}));}late final Dio dio;final TokenStore tokens;}
